#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SC_BATTLE_OUTSIDE_SKIP_RESULT {
    /// 战斗结果0无效的战斗,1胜利,2失败
    pub result: i8,
    /// 战斗奖励
    pub award: Vec<pt_prop_award>,
    /// 战斗奖励详细类
    pub detail_item_award: Vec<pt_prop_bag_detail>,
    /// 玩家经验
    pub player_exp: i32,
    /// 战员经验
    pub hero_exp: i32,
    /// 每个战员加的亲密度
    pub hero_relation: i32,
    /// 预留参数
    pub args: Vec<i32>,
    /// 战员id列表 key  战员敌物id, value  来源
    pub hero_id_list: Vec<pt_attr_int>,
    /// 当前回合数
    pub round: i8,
    /// 战斗统计信息
    pub statistic: Vec<pt_battle_statistic>,
    /// 战场环境
    pub pos_effect: Vec<i32>,
    /// 是否回放
    pub is_replay: i8,
}

impl SC_BATTLE_OUTSIDE_SKIP_RESULT {
    pub fn decode(data: &[u8]) -> Self {
        let mut reader = ProtocolByteBuf::new(data);
        tracing::trace!(command = "SC_BATTLE_OUTSIDE_SKIP_RESULT", data_len = data.len(), "Decoding protocol message");
        Self {
            result: reader.read_i8_padded(),
            award: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_prop_award::decode(&mut reader)); 
            } 
            v 
        },
            detail_item_award: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_prop_bag_detail::decode(&mut reader)); 
            } 
            v 
        },
            player_exp: reader.read_i32_padded(),
            hero_exp: reader.read_i32_padded(),
            hero_relation: reader.read_i32_padded(),
            args: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(reader.read_i32_padded()); 
            } 
            v 
        },
            hero_id_list: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_attr_int::decode(&mut reader)); 
            } 
            v 
        },
            round: reader.read_i8_padded(),
            statistic: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_battle_statistic::decode(&mut reader)); 
            } 
            v 
        },
            pos_effect: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(reader.read_i32_padded()); 
            } 
            v 
        },
            is_replay: reader.read_i8_padded(),
        }
    }
    pub fn encode(&self) -> Vec<u8> {
        let mut buf = ProtocolByteBuf::new_write();
                buf.write_i8(self.result);
                buf.write_count(self.award.len());
        for v in self.award.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
                buf.write_count(self.detail_item_award.len());
        for v in self.detail_item_award.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
                buf.write_i32(self.player_exp);
                buf.write_i32(self.hero_exp);
                buf.write_i32(self.hero_relation);
                buf.write_count(self.args.len());
        for v in self.args.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_i32(*v);
        }
                buf.write_count(self.hero_id_list.len());
        for v in self.hero_id_list.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
                buf.write_i8(self.round);
                buf.write_count(self.statistic.len());
        for v in self.statistic.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
                buf.write_count(self.pos_effect.len());
        for v in self.pos_effect.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_i32(*v);
        }
                buf.write_i8(self.is_replay);
        buf.into_bytes()
    }
}

