#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SC_EQUIP_RECONSTRUCT {
    /// 结果1成功0失败
    pub result: i8,
    /// 战员id
    pub hero_id: i32,
    /// 装备id
    pub equip_id: i32,
    /// 核能技能属性
    pub nuclear_attr: Vec<pt_attr>,
    /// 技能效果
    pub skill_effect: Vec<pt_skill_effect_value>,
}

impl SC_EQUIP_RECONSTRUCT {
    pub fn decode(data: &[u8]) -> Self {
        let mut reader = ProtocolByteBuf::new(data);
        tracing::trace!(command = "SC_EQUIP_RECONSTRUCT", data_len = data.len(), "Decoding protocol message");
        Self {
            result: reader.read_i8_padded(),
            hero_id: reader.read_i32_padded(),
            equip_id: reader.read_i32_padded(),
            nuclear_attr: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_attr::decode(&mut reader)); 
            } 
            v 
        },
            skill_effect: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_skill_effect_value::decode(&mut reader)); 
            } 
            v 
        },
        }
    }
    pub fn encode(&self) -> Vec<u8> {
        let mut buf = ProtocolByteBuf::new_write();
                buf.write_i8(self.result);
                buf.write_i32(self.hero_id);
                buf.write_i32(self.equip_id);
                buf.write_count(self.nuclear_attr.len());
        for v in self.nuclear_attr.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
                buf.write_count(self.skill_effect.len());
        for v in self.skill_effect.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
        buf.into_bytes()
    }
}

