#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct pt_skill_effect_value {
    /// 技能id
    pub skill_id: i32,
    /// 技能等级
    pub skill_lv: i32,
    /// 效果列表
    pub effect_values: Vec<pt_effect_values>,
}

impl pt_skill_effect_value {
    pub fn decode(reader: &mut ProtocolByteBuf) -> Self {
        Self {
            skill_id: reader.read_i32_padded(),
            skill_lv: reader.read_i32_padded(),
            effect_values: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_effect_values::decode(reader)); 
            } 
            v 
        },
        }
    }
    pub fn encode(&self) -> Vec<u8> {
        let mut buf = ProtocolByteBuf::new_write();
                buf.write_i32(self.skill_id);
                buf.write_i32(self.skill_lv);
                buf.write_count(self.effect_values.len());
        for v in self.effect_values.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
        buf.into_bytes()
    }
}

