#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct pt_battle_element {
    /// 战斗元素id
    pub id: i32,
    /// 势力 1-攻方 2-守方
    pub side: i8,
    /// 类型 1-战员 2-神器
    pub int8: pt_type,
    /// 位置
    pub pos: i8,
    /// 模板id
    pub tid: i32,
    /// 等级
    pub lv: i16,
    /// 星级
    pub star: i16,
    /// 伤害总量
    pub hurt: String,
    /// 治疗总量
    pub cure: String,
    /// 受伤总量
    pub be_hurt: String,
    /// 当前血量
    pub hp: String,
    /// 最大血量
    pub max_hp: String,
    /// 时装id
    pub cloth_id: i16,
}

impl pt_battle_element {
    pub fn decode(reader: &mut ProtocolByteBuf) -> Self {
        Self {
            id: reader.read_i32_padded(),
            side: reader.read_i8_padded(),
            int8: pt_type::decode(reader),
            pos: reader.read_i8_padded(),
            tid: reader.read_i32_padded(),
            lv: reader.read_i16_padded(),
            star: reader.read_i16_padded(),
            hurt: reader.read_i64_padded().to_string(),
            cure: reader.read_i64_padded().to_string(),
            be_hurt: reader.read_i64_padded().to_string(),
            hp: reader.read_i64_padded().to_string(),
            max_hp: reader.read_i64_padded().to_string(),
            cloth_id: reader.read_i16_padded(),
        }
    }
    pub fn encode(&self) -> Vec<u8> {
        let mut buf = ProtocolByteBuf::new_write();
                buf.write_i32(self.id);
                buf.write_i8(self.side);
                buf.write_raw_bytes(&self.int8.encode());
                buf.write_i8(self.pos);
                buf.write_i32(self.tid);
                buf.write_i16(self.lv);
                buf.write_i16(self.star);
                buf.write_i64(self.hurt.parse::<i64>().unwrap_or_default());
                buf.write_i64(self.cure.parse::<i64>().unwrap_or_default());
                buf.write_i64(self.be_hurt.parse::<i64>().unwrap_or_default());
                buf.write_i64(self.hp.parse::<i64>().unwrap_or_default());
                buf.write_i64(self.max_hp.parse::<i64>().unwrap_or_default());
                buf.write_i16(self.cloth_id);
        buf.into_bytes()
    }
}

