#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct pt_mail_info {
    /// 唯一id
    pub id: i32,
    /// 邮件种类
    #[serde(rename = "type")]
    pub msg_type: i8,
    /// 标题
    pub title: String,
    /// 日期秒
    pub date: i32,
    /// 过期时间秒
    pub expired_time: i32,
    /// 状态
    pub state: i8,
    /// 内容
    pub content: String,
    /// 发件人
    pub send_name: String,
    /// 道具奖励列表
    pub award_list: Vec<pt_prop_bag_detail>,
    /// 称呼
    pub call: String,
    /// 是否可收藏0-否,1-是
    pub is_collection: i8,
}

impl pt_mail_info {
    pub fn decode(reader: &mut ProtocolByteBuf) -> Self {
        Self {
            id: reader.read_i32_padded(),
            msg_type: reader.read_i8_padded(),
            title: reader.read_string_padded(),
            date: reader.read_i32_padded(),
            expired_time: reader.read_i32_padded(),
            state: reader.read_i8_padded(),
            content: reader.read_string_padded(),
            send_name: reader.read_string_padded(),
            award_list: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_prop_bag_detail::decode(reader)); 
            } 
            v 
        },
            call: reader.read_string_padded(),
            is_collection: reader.read_i8_padded(),
        }
    }
    pub fn encode(&self) -> Vec<u8> {
        let mut buf = ProtocolByteBuf::new_write();
                buf.write_i32(self.id);
                buf.write_i8(self.msg_type);
                buf.write_string(&self.title);
                buf.write_i32(self.date);
                buf.write_i32(self.expired_time);
                buf.write_i8(self.state);
                buf.write_string(&self.content);
                buf.write_string(&self.send_name);
                buf.write_count(self.award_list.len());
        for v in self.award_list.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
                buf.write_string(&self.call);
                buf.write_i8(self.is_collection);
        buf.into_bytes()
    }
}

