impl pt_battle_hero {
    pub fn decode(reader: &mut ProtocolByteBuf) -> Self {
        Self {
            id: reader.read_i32_padded(),
            tid: reader.read_i32_padded(),
            msg_type: reader.read_i8_padded(),
            pos: pt_pos::decode(reader),
            max_hp: reader.read_i64_padded().to_string(),
            hp: reader.read_i64_padded().to_string(),
            rage: reader.read_i32_padded(),
            skill_soul: reader.read_i8_padded(),
            lv: reader.read_i16_padded(),
            evolution: reader.read_i16_padded(),
            color: reader.read_i16_padded(),
            skill_list: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_battle_hero_skill::decode(reader)); 
            } 
            v 
        },
            body_fashion_id: reader.read_i16_padded(),
            hit_stun: reader.read_i16_padded(),
            max_hit_stun: reader.read_i16_padded(),
            auto_battle_rule: reader.read_i16_padded(),
            body_fashion_color_id: reader.read_i16_padded(),
            star_lv: reader.read_i16_padded(),
        }
    }
    pub fn encode(&self) -> Vec<u8> {
        let mut buf = ProtocolByteBuf::new_write();
                buf.write_i32(self.id);
                buf.write_i32(self.tid);
                buf.write_i8(self.msg_type);
                buf.write_raw_bytes(&self.pos.encode());
                buf.write_i64(self.max_hp.parse::<i64>().unwrap_or_default());
                buf.write_i64(self.hp.parse::<i64>().unwrap_or_default());
                buf.write_i32(self.rage);
                buf.write_i8(self.skill_soul);
                buf.write_i16(self.lv);
                buf.write_i16(self.evolution);
                buf.write_i16(self.color);
                buf.write_count(self.skill_list.len());
        for v in self.skill_list.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
                buf.write_i16(self.body_fashion_id);
                buf.write_i16(self.hit_stun);
                buf.write_i16(self.max_hit_stun);
                buf.write_i16(self.auto_battle_rule);
                buf.write_i16(self.body_fashion_color_id);
                buf.write_i16(self.star_lv);
        buf.into_bytes()
    }
}

