#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SC_NEW_YEAR_TURNTABLE_LOTTERY {
    /// 0-失败,1-成功
    pub result: i8,
    /// 1次 or 10次
    pub times: i8,
    /// 未抽中目标道具次数(幸运值)
    pub unlucky_times: i16,
    /// 累计抽奖次数
    pub acc_times: i32,
    /// 抽奖顺序列表
    pub order_list: Vec<i32>,
    /// 获得奖励
    pub award: Vec<pt_prop_award>,
}

impl SC_NEW_YEAR_TURNTABLE_LOTTERY {
    pub fn decode(data: &[u8]) -> Self {
        let mut reader = ProtocolByteBuf::new(data);
        tracing::trace!(command = "SC_NEW_YEAR_TURNTABLE_LOTTERY", data_len = data.len(), "Decoding protocol message");
        Self {
            result: reader.read_i8_padded(),
            times: reader.read_i8_padded(),
            unlucky_times: reader.read_i16_padded(),
            acc_times: reader.read_i32_padded(),
            order_list: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(reader.read_i32_padded()); 
            } 
            v 
        },
            award: { 
            let count = reader.read_count_padded();
            let mut v = Vec::with_capacity(count); 
            for _ in 0..count { 
                v.push(pt_prop_award::decode(&mut reader)); 
            } 
            v 
        },
        }
    }
    pub fn encode(&self) -> Vec<u8> {
        let mut buf = ProtocolByteBuf::new_write();
                buf.write_i8(self.result);
                buf.write_i8(self.times);
                buf.write_i16(self.unlucky_times);
                buf.write_i32(self.acc_times);
                buf.write_count(self.order_list.len());
        for v in self.order_list.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_i32(*v);
        }
                buf.write_count(self.award.len());
        for v in self.award.iter().take(MAX_COLLECTION_ITEMS) {
            buf.write_raw_bytes(&v.encode());
        }
        buf.into_bytes()
    }
}

